def xp_necessario(nivel):
    return 100 * nivel ** 2


def barra_de_vida(vida, maximo):
    cheias = vida * 10 // maximo
    return "[" + "#" * cheias + "-" * (10 - cheias) + "]"


def main():
    print("XP para o nível 5:", xp_necessario(5))
    print("Vida:", barra_de_vida(60, 100))


